import json, random, subprocess, sys, time, os
sys.path.insert(0,'/workspace/submission')

def build(clustered, nruns, nburst, naddr):
    rng = random.Random(7)
    # produce exactly nruns canonical runs
    routes = [["::/0", 1]]
    starts = [0]
    n = nruns - 2   # one leading ::/0 run plus trailing run
    for i in range(1, n + 1):
        if clustered:
            base = i
        else:
            base = (1 << 100) * i + rng.randrange(0, 1 << 60)
        routes.append([str_ip(base), 128, i + 1])
    starts = [0] + [base_for(routes[i][0]) for i in range(1, len(routes))]
    bursts = []
    addrs = []
    total = 0
    for b in range(nburst):
        na = min(naddr // max(1, nburst), 64)
        lst = []
        for _ in range(na):
            if clustered:
                a = rng.randrange(0, n + 2)
            else:
                a = (1 << 100) * rng.randrange(0, n + 2)
            lst.append(str_ip(a))
            total += 1
        bursts.append({"version": 0, "repeat": rng.randrange(1, 1000), "addresses": lst})
    case = {"initial": routes, "transactions": [], "bursts": bursts,
            "cache_pages": 12, "costs": {"hit": 2, "miss": 20, "decode": [0, 1, 2]}}
    return {"cases": [case]}

def str_ip(x):
    import ipaddress
    return str(ipaddress.IPv6Address(x))

def base_of(t):
    import ipaddress
    return int(ipaddress.IPv6Address(t))

def base_for(t):
    return base_of(t)

if __name__ == '__main__':
    clustered = sys.argv[1] == 'clustered'
    req = build(clustered, 64, 128, 4000)
    data = json.dumps(req).encode()
    open('/tmp/perf.json','wb').write(data)
    t = time.time()
    p = subprocess.run([sys.executable, '-B', '/workspace/submission/main.py'], input=data,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    print('rc', p.returncode, 'time %.1fs' % (time.time() - t), 'out', len(p.stdout))
    if p.returncode: print(p.stderr[:2000])
    else:
        r = json.loads(p.stdout)
        print('objective', r['cases'][0]['objective'])
EOF
